s a topic/aggregate page rather than a verified individual article.","verification_status":"aggregate_and_source_scope_review_pending","name":"overview.legal","publisher_id":"1eb81b68-a366-4624-a4ca-7987b59f7203","jurisdiction":"EU","publisher_type":"media","approval_basis":"User requested inclusion in the complete tested-source scope. Runtime access, full-body extraction, topic relevance, date evidence, and source-specific route have not all been verified; do not collect or write.","source_kind":"html"}]$items$::jsonb) loop
  insert into public.publishers(id,name,acronym,jurisdiction_code,publisher_type,website_url,is_active)
  values((c->>'publisher_id')::uuid,c->>'name',upper(c->>'source'),c->>'jurisdiction',c->>'publisher_type','https://' || (c#>>'{hosts,0}'),false)
  on conflict(id) do nothing;
  insert into public.sources(id,publisher_id,name,source_kind,fetch_strategy,start_url,parser_config,poll_interval_minutes,respect_robots,terms_reviewed_at,is_active)
  values((c->>'source_id')::uuid,(c->>'publisher_id')::uuid,c->>'name',c->>'source_kind','http',c->>'listing',jsonb_build_object('automatic_collection_enabled',false,'collector_executor','hold','hold_reason',c->>'hold_reason','verification_status',c->>'verification_status','verification',c->>'verification','approval_basis',c->>'approval_basis'),case when c->>'cadence'='weekly' then 10080 else 1440 end,true,null,false)
  on conflict(id) do nothing;
 end loop;
end; $catalog_sources$;

